import math

def inverse_cdf_tdist(P, nu):
    # Load required libraries
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define function signature
    gsl_cdf_tdist_Pinv = gsl.gsl_cdf_tdist_Pinv
    gsl_cdf_tdist_Pinv.argtypes = [ctypes.c_double, ctypes.c_double]
    gsl_cdf_tdist_Pinv.restype = ctypes.c_double

    # Handle edge cases
    if P == 0:
        return -float('inf')
    if P == 1:
        return float('inf')
    if nu == 1:
        # Cauchy distribution, use arctangent
        return math.tan(math.pi * (P - 0.5))
    if nu == 2:
        # Chi-squared distribution with 2 degrees of freedom
        return math.sqrt(-2 * math.log(P))

    # Call GSL function
    return gsl_cdf_tdist_Pinv(P, nu)

