class GSLMatrix:
    def __init__(self, data, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = np.ctypespointer(np.float64, data)

    def __del__(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL).gsl_matrix_free(ctypes.pointer(self))

    @property
def get_matrix(self):
    return self.data


def gsl_matrix_alloc(rows, cols):
    return ctypes.pointer(ctypes.Structure._fields_([("data", ctypes.POINTER(ctypes.c_double)),
                                                      ("rows", ctypes.c_int),
                                                      ("cols", ctypes.c_int)]))


def gsl_matrix_free(matrix):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL).gsl_matrix_free(matrix)


def numpy_to_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray):
        raise ValueError("Input must be a numpy array")
    if np_array.ndim != 2:
        raise ValueError("Input must be a 2D array")
    rows, cols = np_array.shape
    gsl_matrix = gsl_matrix_alloc(rows, cols)
    gsl_matrix.contents.data = np.ascontiguousarray(np_array).ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    gsl_matrix.contents.rows = rows
    gsl_matrix.contents.cols = cols
    return gsl_matrix


def gsl_matrix_to_numpy(gsl_matrix):
    if gsl_matrix.contents.rows <= 0 or gsl_matrix.contents.cols <= 0:
        raise ValueError("Invalid matrix dimensions")
    np_array = np.ctypeslib.as_array(gsl_matrix.contents.data, shape=(gsl_matrix.contents.rows, gsl_matrix.contents.cols))
    return np_array


def gsl_multifit_covar(jacobian, epsrel):
    if jacobian.contents.rows != jacobian.contents.cols:
        raise ValueError("Jacobian must be square matrix")
    if epsrel <= 0:
        raise ValueError("epsrel must be positive")

    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    covar = gsl_matrix_alloc(jacobian.contents.rows, jacobian.contents.cols)

    gsl.gsl_multifit_covar(jacobian, epsrel, covar)

    return gsl_matrix_to_numpy(covar)


def compute_covariance(jacobian, epsrel, n):
    if jacobian.ndim != 2:
        raise ValueError("Jacobian must be 2D array")
    if jacobian.shape[0] != jacobian.shape[1]:
        raise ValueError("Jacobian must be square matrix")
    if n <= 0:
        raise ValueError("n must be positive")

    gsl_jacobian = numpy_to_gsl_matrix(jacobian)

    covar = gsl_multifit_covar(gsl_jacobian, epsrel)

