class gsl_complex(ctypes.Structure):
    _fields_ = [
        ('_real', ctypes.c_double),
        ('_imag', ctypes.c_double)
    ]

    def __init__(self, real, imag):
        self._real = real
        self._imag = imag

    def __getattr__(self, name):
        if name == 'real':
            return self._real
        elif name == 'imag':
            return self._imag
        else:
            raise AttributeError(name)

    def __setattr__(self, name, value):
        if name == 'real':
            self._real = value
        elif name == 'imag':
            self._imag = value
        else:
            super().__setattr__(name, value)

# Define the GSL function
gsl.gsl_complex_real.argtypes = [ctypes.POINTER(gsl_complex)]
gsl.gsl_complex_real.restype = ctypes.c_double

def get_real_parts(complex_numbers):
    real_parts = []
    for num in complex_numbers:
        # Convert the complex number to a gsl_complex structure
        gsl_complex_obj = gsl_complex(num.real, num.imag)
        # Call the GSL function to get the real part
        real_part = gsl.gsl_complex_real(ctypes.pointer(gsl_complex_obj))
        real_parts.append(real_part)
    return real_parts

