import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        self.data = (ctypes.c_double * (self.rows * self.cols))()

    def free(self):
        self.data = None

    def to_numpy(self):
        return np.array([self.data[i*self.cols:(i+1)*self.cols] for i in range(self.rows)], dtype=np.float64)

    def list_to_ctypes_matrix(lst):
        mat = GSLMatrix(len(lst), len(lst[0]))
        for i in range(mat.rows):
            for j in range(mat.cols):
                mat.data[i*mat.cols + j] = lst[i][j]
        return mat

    def list_to_ctypes_matrix(lst):
        mat = GSLMatrix(len(lst), len(lst[0]))
        for i in range(mat.rows):
            for j in range(mat.cols):
                mat.data[i*mat.cols + j] = lst[i][j]
        return mat

    def compute_covariance(jacobian, epsrel):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gslcblas.gsl_multifit_nlinear_covar.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_int, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.c_int]
        gslcblas.gsl_multifit_nlinear_covar.restype = ctypes.c_int

        jacobian_ptr = ctypes.pointer(jacobian.to_numpy())
        n = jacobian.rows
        m = jacobian.cols
        epsrel_val = epsrel
        covar = GSLMatrix(n, n)
        covar_ptr = ctypes.pointer(covar.data)

        status = gslcblas.gsl_multifit_nlinear_covar(jacobian_ptr, n, m, epsrel_val, covar_ptr, n)
        if status != 0:
            raise RuntimeError(f"Error in gsl_multifit_nlinear_covar: {status}")

        return covar.to_numpy()

