    _fields_ = [
        ("function", ctypes.POINTER(ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)) ),
        ("params", ctypes.c_void_p)
    ]

def func_wrapper(x, params):
