    return py_func(x)

def compute_integral(py_func, a, b, epsabs, epsrel, n):
    # Create function object
    func = gsl_function()
    func.function = ctypes.pointer(ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(func_wrapper))
    func.params = ctypes.pointer(ctypes.c_void_p())
    ctypes.cast(func.params, ctypes.c_void_p()).value = ctypes.pointer(py_func)

    # Allocate Romberg workspace
    workspace = gsl.gsl_integration_romberg_alloc(n)

    # Compute integral
    result = ctypes.c_double(0)
    evaluations = ctypes.c_int(0)
    gsl.gsl_integration_romberg(workspace, func, a, b, epsabs, epsrel, ctypes.byref(result), ctypes.byref(evaluations))

    # Free workspace
    gsl.gsl_integration_romberg_free(workspace)

    return float(result.value), int(evaluations.value)

